func PathEscape(pth string) string {
	// The hash sign is a valid path character in Hugo, but net/url treats it
	// as the start of a URL fragment, so escape it before parsing.
	pth = strings.ReplaceAll(pth, "#", "%23")
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

